processPrePosts.script:
if (tw.local.hubCode!= null && tw.local.hubCode != "" && tw.local.crMaker == true) {
	tw.local.TEAM_NAME = tw.epv.TeamsNameBPM.HUB_CR_MKR+"";
	tw.local.TEAM_MANAGER = tw.epv.TeamsNameBPM.HUB_CR_MKR_Manager+"";
	tw.local.PARENT_TEAM_NAME = "" + tw.epv.BPMTeamsNamesReassign.idc_hub_cr;
}
else if (tw.local.hubCode!= null && tw.local.hubCode != "" && tw.local.crMaker == false){
	tw.local.TEAM_NAME = tw.epv.TeamsNameBPM.HUB_EXE_MKR+"";
	tw.local.TEAM_MANAGER = tw.epv.TeamsNameBPM.HUB_EXE_Manager+"";
	tw.local.PARENT_TEAM_NAME = "" + tw.epv.BPMTeamsNamesReassign.idc_hub_exe_Maker;
}
else{
	tw.local.TEAM_NAME = tw.epv.TeamsNameBPM.Branches_Operation_Makers+"";
	tw.local.TEAM_MANAGER = tw.epv.TeamsNameBPM.BranchMakerManager+"";
	tw.local.PARENT_TEAM_NAME = "" + tw.epv.BPMTeamsNamesReassign.Branch_Opereration_Maker;
}

